class _AppStringsDelegate extends LocalizationsDelegate<AppStrings> {
  const _AppStringsDelegate();
  @override bool isSupported(Locale locale) => AppStrings.supportedLocales.any((x) => x.languageCode == locale.languageCode && (x.countryCode == null || x.countryCode == locale.countryCode));
  @override Future<AppStrings> load(Locale locale) async => AppStrings(locale);
  @override bool shouldReload(covariant LocalizationsDelegate<AppStrings> old) => false;
}
